function OverseaManageCafeCattyDialog:__init()
    self.component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
end

function OverseaManageCafeCattyDialog:Awake()
    self:InitNodeEnv()
    self.refreshEvent = Events.AddListener("MaidCoffee.RefreshCondition",Bind(self,self.RefreshConditionShow))
end

function OverseaManageCafeCattyDialog:RefreshConditionShow()
    self:RequestShow(true)
end

function OverseaManageCafeCattyDialog:InitNodeEnv()
    if self.PanelRight1 then
        local env = CfUtils.GetLuaScr(self.PanelRight1.gameObject,LevelUpPath)
        if env then
            env:SetCallBack(Bind(self,self.OnLevelUpSuccess))
            self.levelUpEnv = env
        end
    end

    if self.PanelRight2 then
        local env = CfUtils.GetLuaScr(self.PanelRight2.gameObject,StarUpPath)
        if env then
            env:SetCallBack(Bind(self,self.RefreshShow))
            self.starUpEnv = env
        end
    end

    if self.PanelLeft then
        local env = CfUtils.GetLuaScr(self.PanelLeft.gameObject,LeftRootPath)
        if env then
            self.leftRootEnv = env
        end
    end

    KTool.SetActive(self.AniRoot.gameObject,false)
end

function OverseaManageCafeCattyDialog:OnFocus(focus)
    GameUtils.RefreshTopGoods(Constants.UITypeIds.UIMaidCoffeeCattyMain)
end

function OverseaManageCafeCattyDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self:RequestShow()
            local isLevelUp = self.component:GetCurIsLevelUp()
            if isLevelUp then
                MaidCoffeeUtils.PlayMusicById(MaidCoffeeConstants.MaidCoffeeMusicName.CattyLevelUp)
            else
                MaidCoffeeUtils.PlayMusicById(MaidCoffeeConstants.MaidCoffeeMusicName.CattyStarUp)
            end
        end)
    end))
    return coWait
end

function OverseaManageCafeCattyDialog:RequestShow(isLevelUp)
    if  isNull(self.component) then return end
    GameUtils.Request(Interfaces.MaidCoffeeLevelTask,{},
            function(request,response)
                if checkInt(response.errCode) == 0 then
                    local maidCoffeeHomeDojo = self.component:GetMaidCoffeeHomeDoJo()
                    maidCoffeeHomeDojo:UpdateLevelTaskProgress(response.data.levelTaskProgress)
                    self:RefreshShow(isLevelUp)
                end
            end)
end

function OverseaManageCafeCattyDialog:OnLevelUpSuccess()
    self:RefreshShow(true)
end

function OverseaManageCafeCattyDialog:RefreshShow(_isLevelUp)
    local isToMax = self.component:GetIsToMaxStar()
    self.leftRootEnv:SetStarAndLevelShow(isToMax)
    KTool.SetActive(self.AniRoot.gameObject,true)
    local AniName = "OverseaManageCafeCattyDialog_Up"
    if isToMax then
        AniName = "OverseaManageCafeCattyDialog_MAX"
        KTool.SetActive(self.PanelRight1.gameObject,false)
        KTool.SetActive(self.PanelRight2.gameObject,false)
    else
        local isLevelUp = self.component:GetCurIsLevelUp()
        self:SetRootShow(isLevelUp)
        if isLevelUp then
            self.levelUpEnv:RefreshShow(function() self:RequestShow(true)  end)
        else
            _isLevelUp = false
            AniName = "OverseaManageCafeCattyDialog_Star"
            self.starUpEnv:RefreshShow()
        end
    end
    if _isLevelUp then
        return
    end

    self.AniRoot:Play(AniName)
end


function OverseaManageCafeCattyDialog:SetRootShow(status)
    KTool.SetActive(self.PanelRight1.gameObject,status)
    KTool.SetActive(self.PanelRight2.gameObject,not status)
end

